/// <reference types="vite/client" />
/// <reference types="vite-imagetools/client" />

declare module '*?webp' {
  const src: string;
  export default src;
}

declare module '*?format=webp' {
  const src: string;
  export default src;
}

declare module '*?webp&w=768' {
  const src: string;
  export default src;
}

declare module '*?webp&w=1280' {
  const src: string;
  export default src;
}

declare module '*?webp&w=1920' {
  const src: string;
  export default src;
}
